SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(rating) AS total_rating, COUNT(*) AS cnt, DENSE_RANK() OVER (ORDER BY SUM(rating) DESC) AS rnk FROM suppliers GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END ORDER BY cnt DESC, 1
